const errorText = (e: unknown) => e instanceof Error ? e.message : 'The request could not be completed.';
const workflow = (s: string) => s.replaceAll('_', ' ');
const disclaimer = 'Manual review of submitted evidence; no live system verification performed.';
const readiness: Readiness[] = ['Not closure ready', 'Implemented but evidence incomplete', 'Ready for retest', 'Closure ready'];
const statuses = ['open', 'remediation_in_progress', 'evidence_submitted', 'under_review', 'changes_requested', 'retest_pending', 'awaiting_closure_decision', 'review_completed', 'awaiting_final_approval', 'closed'];
const text = (data: FormData, name: string) => String(data.get(name) || '').trim();

function ManualFindingList({ findings, queue = false, filtered = false }: { findings: ManualFinding[]; queue?: boolean; filtered?: boolean }) {
  if (!findings.length && filtered) return <Empty title="No matching findings" description="Change the search or filters to see more records." />;
  if (!findings.length && queue) return <Empty title="No findings awaiting review" description="Findings submitted with evidence will appear here when they need review. Published reviews remain in each finding's history." />;
  if (!findings.length) return <Empty title="No findings submitted" description="Create a finding, record its scope and upload evidence for a person to inspect." action={<Link className={buttonClass} to="/app/findings/new">Submit a finding</Link>} />;
  return <div className="divide-y divide-line">{findings.map(f => <Link className="flex flex-wrap items-start justify-between gap-4 py-5" key={f.id} to={(queue ? '/app/reviews/' : '/app/findings/') + f.id + (queue&&f.lifecycle==='review_completed'&&f.currentReview?.status==='completed'?'?assessment='+f.currentReview.id:'')}><div className="min-w-0 flex-1"><p className="break-words text-sm font-semibold">{f.title}</p><p className="mt-2 text-xs text-muted">Finding ID: {f.findingReference||f.id}</p><p className="mt-2 text-xs leading-6 text-muted">{f.account_reference} · {f.owner} · {f.protocol.title}<br />{f.evidenceCount} evidence file(s) · {workflow(f.lifecycle)}{f.deadline ? ` · Due ${f.deadline}` : ''}</p></div><div className="flex items-center gap-3">{f.lifecycle==='changes_requested'&&<Badge tone="red">Remediation requested</Badge>}<Badge tone={f.severity === 'High' ? 'red' : 'neutral'}>{f.severity}</Badge>{f.readiness ? <StateBadge state={f.readiness} /> : <Badge>Not reviewed</Badge>}{queue&&f.lifecycle==='review_completed'&&f.currentReview?.status==='completed'&&<span className="text-xs font-semibold text-accent">Edit review</span>}<ArrowRight size={16} className="text-accent" /></div></Link>)}</div>;
}

export function ManualFindingsPage({ queue = false }: { queue?: boolean }) {
  const { manualFindings, loading, error } = useWorkspace(); const [search, setSearch] = useState(''); const [status, setStatus] = useState(''); const [params, setParams] = useSearchParams(); const readinessFilter = params.get('readiness') || ''; const [severity, setSeverity] = useState('');
  const available = queue ? manualFindings.filter(f => ['evidence_submitted', 'under_review', 'retest_pending', 'review_completed', 'changes_requested', 'awaiting_final_approval', 'closed'].includes(f.lifecycle)) : manualFindings;
  const filtered = available.filter(f => (!search || `${f.title} ${f.account_reference} ${f.owner} ${f.protocol.title} ${f.source_report?.filename||''} ${f.source_report?.run_id||f.id} ${f.submissionReference||''} ${f.findingReference||''}`.toLowerCase().includes(search.toLowerCase())) && (!status || f.lifecycle === status) && (!severity || f.severity === severity) && (!readinessFilter || (readinessFilter === 'gaps' ? ['Not closure ready', 'Implemented but evidence incomplete'].includes(f.readiness || '') : readinessFilter === 'unreviewed' ? !f.readiness : f.readiness === readinessFilter)));
  if (loading) return <Loading />;
  return <><PageHeader eyebrow={queue ? 'Review' : 'Manual submissions'} title={queue ? 'Reviewer queue' : 'Findings'} description={queue ? 'Browse report submissions, choose a finding and open its review workspace to inspect evidence and record your recommendation.' : 'Security findings, submitted evidence and reviewer-authored recommendations.'} action={!queue && <Link className={buttonClass} to="/app/findings/new"><Plus size={16} />Submit a finding</Link>} /><Card><div className="mb-6 grid gap-4 sm:grid-cols-2 xl:grid-cols-4"><Field label="Search findings"><input value={search} onChange={e => setSearch(e.target.value)} placeholder={queue?"Report name, submission ID, finding or owner":"Title, account, owner or protocol"} /></Field><Field label="Workflow status"><select value={status} onChange={e => setStatus(e.target.value)}><option value="">All statuses</option>{statuses.map(s => <option key={s} value={s}>{workflow(s)}</option>)}</select></Field><Field label="Severity filter"><select value={severity} onChange={e => setSeverity(e.target.value)}><option value="">All severities</option>{['High', 'Medium', 'Low'].map(s => <option key={s}>{s}</option>)}</select></Field><Field label="Filter by readiness"><select value={readinessFilter} onChange={e => { const next = new URLSearchParams(params); if (e.target.value) next.set('readiness',e.target.value); else next.delete('readiness'); setParams(next); }}><option value="">All reviewer recommendations</option><option value="unreviewed">Awaiting review</option><option value="gaps">Evidence gaps recorded by reviewer</option>{readiness.map(s => <option key={s}>{s}</option>)}</select></Field></div>{error ? <p className="text-sm text-muted">{queue ? 'The review queue' : 'The finding register'} cannot load records until the review service reconnects.</p> : queue?<ReviewSubmissionList findings={filtered} filtered={!!(search || status || severity || readinessFilter)}/>:<ReviewSubmissionList findings={filtered} filtered={!!(search || status || severity || readinessFilter)} queue={false}/>}</Card></>;
}

const findingFields = [
  ['account_reference', 'Source account / environment reference', true], ['affected_systems', 'Affected systems / environment', true],
  ['resources', 'Affected identities and resource references', true], ['approved_baseline', 'Approved access / control baseline', false],
  ['root_cause', 'Root cause', false], ['recurrence_prevention', 'Recurrence prevention', false], ['corrective_action', 'Corrective action', false],
] as const;

export function ManualFindingCreate({ existing, onSaved, reportDraft, onSubmitted, submitLabel, requireEvidence=false }: { existing?: ManualFinding; onSaved?: (f: ManualFinding) => void; reportDraft?: {id:string;index:number}; onSubmitted?: (finding:ManualFinding)=>void; submitLabel?:string; requireEvidence?:boolean }) {
  const [submissionMode,setSubmissionMode]=useState<'report'|'manual'|null>(null);
  const [attachments,setAttachments]=useState<SubmissionAttachment[]>([]);
  const [evidenceDraftOpen,setEvidenceDraftOpen]=useState(false);
  const persistedId=useRef<string|null>(null);const savedFinding=useRef<ManualFinding|null>(null);const savedForm=useRef<FormData|null>(null);
  const [partialId,setPartialId]=useState('');const [progress,setProgress]=useState('');
  const submitting=useRef(false);
  const [protocols, setProtocols] = useState<ManualProtocol[]>([]); const [error, setError] = useState(''); const [busy, setBusy] = useState(false);
  const [protocolCode, setProtocolCode] = useState(existing?.protocol_code || 'access');
  const [scopeRequest, setScopeRequest] = useState(emptyScope);
  const [params] = useSearchParams();
  const runId = existing ? '' : reportDraft?.id || params.get('analysis') || '';
  const draftIndex = reportDraft?.index ?? Number(params.get('draft') || '0');
  const [sourceReport,setSourceReport] = useState<PublicAnalysisRun|null>(null);
  const [sourceConfirmed,setSourceConfirmed] = useState(false);
  useEffect(() => { setSourceReport(null); setSourceConfirmed(false); if(!runId)return; let cancelled=false; documentApi.get(runId).then(run=>{ if(cancelled)return; if(run.mode!=='report'||run.status!=='ready'||!Number.isInteger(draftIndex)||draftIndex<0||!run.result?.findings[draftIndex])throw Error('This extracted finding draft is unavailable.'); setSourceReport(run);setScopeRequest(emptyScope());setProtocolCode(''); }).catch(e=>{if(!cancelled)setError(errorText(e));});return()=>{cancelled=true;}; },[runId,draftIndex]);
  const draft = sourceReport?.result?.findings[draftIndex];
  const initial: Partial<FindingInput> = existing || (draft ? Object.fromEntries(Object.entries(draft.fields).filter(([,value])=>value!==null)) : {});
  const imported = existing?.protocol.code === 'legacy-unassigned';
  const navigate = useNavigate(); const w = useWorkspace();
  useEffect(() => { manualApi.protocols().then(setProtocols).catch(e => setError(errorText(e))); }, []);
  async function save(event: FormEvent<HTMLFormElement>) {
    event.preventDefault(); if(submitting.current)return;if(requireEvidence&&!attachments.length&&!persistedId.current){setError('Add supporting evidence before continuing to the next step.');return;}if(evidenceDraftOpen){setError('Add the evidence details to the list or cancel that entry before submitting the finding.');return;}const data = savedForm.current||new FormData(event.currentTarget);
    const body = Object.fromEntries(['title', 'description', 'owner', 'severity', 'protocol_code', 'control_reference', ...findingFields.map(([key]) => key)].map(key => [key, text(data, key)])) as unknown as FindingInput;
    body.implementation_date = text(data, 'implementation_date') || null; body.deadline = text(data, 'deadline') || null;
    if (existing) body.revision = existing.revision;
    else body.scope_request = scopeRequest;
    setBusy(true); setError('');
    submitting.current=true;
    try {
      if(attachments.length>30||attachments.reduce((total,item)=>total+item.file.size,0)>250*1024*1024)throw Error('Use at most 30 evidence files totalling 250 MB.');
      const hashes=new Map<string,string>();
      for(const item of attachments){setProgress('Checking '+item.file.name+'…');hashes.set(item.id,(await validateDemoFile(item.file)).digest);}
      const remember=(id:string)=>{persistedId.current=id;savedForm.current=data;setPartialId(id);};
      async function createFromReport(){const id=await documentApi.createFinding(runId,draftIndex,body,scopeRequest,text(data,'draft_confirmed_by'));remember(id);return manualApi.finding(id);}
      let result=savedFinding.current || (persistedId.current?await manualApi.finding(persistedId.current):existing ? await manualApi.update(existing.id, body) : runId ? await createFromReport() : await manualApi.create(body, w.orgId,remember));
      savedFinding.current=result;savedForm.current=data;setPartialId(result.id);
      for(let index=0;index<attachments.length;index++){
        const item=attachments[index];setProgress(`Uploading evidence ${index+1} of ${attachments.length}: ${item.file.name}`);
        result=await manualApi.finding(result.id);
        if(!result.evidence?.some(file=>file.filename===item.file.name&&file.sha256===hashes.get(item.id))){
          await manualApi.upload(result.id,item.file,{revision:result.revision,evidence_type:item.evidenceType,source_system:item.sourceSystem,source_account:item.sourceAccount,covered_resources:item.coveredResources,description:item.description,submitted_by:item.submittedBy,captured_at:item.capturedAt||null,period_start:item.periodStart||null,period_end:item.periodEnd||null,supersedes_id:null});
        }
      }
      result=attachments.length?await manualApi.finding(result.id):result;
      await w.refresh();onSaved?.(result);if(onSubmitted)onSubmitted(result);else navigate('/app/findings/'+result.id);
    } catch(e){setError((savedFinding.current||persistedId.current)?'The finding is saved, but submission has not finished. '+errorText(e)+' Retry to upload only the remaining evidence; another finding will not be created.':errorText(e));}
    finally{setBusy(false);setProgress('');submitting.current=false;}
  }

  if(!existing&&!runId&&!partialId&&!submissionMode)return <><PageHeader eyebrow="New submission" title="Submit a finding" description="Choose how you would like to submit your findings and supporting evidence."/><div className="grid max-w-4xl gap-5 md:grid-cols-2">{[{mode:'report' as const,title:'Upload audit report',description:'Upload a PDF or DOCX report, review the extracted findings and attach evidence to each finding.',Icon:FileText},{mode:'manual' as const,title:'Enter finding manually',description:'Enter the finding details yourself, select the relevant controls and attach supporting evidence.',Icon:ClipboardCheck}].map(({mode,title,description,Icon})=><button key={mode} type="button" aria-label={title} onClick={()=>setSubmissionMode(mode)} className="rounded-2xl border border-line bg-white p-6 text-left transition hover:border-accent/50 focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-accent"><Icon size={28} className="text-accent" aria-hidden="true"/><h2 className="mt-5 font-display text-xl font-semibold">{title}</h2><p className="mt-3 text-sm leading-7 text-muted">{description}</p><span className="mt-5 inline-flex items-center gap-2 text-sm font-semibold text-accent">Continue<ArrowRight size={16}/></span></button>)}</div></>;
  if(runId&&!sourceReport)return error?<Notice error>{error}</Notice>:<Loading />;
  return <><PageHeader eyebrow={runId||submissionMode==='report'?'Report submission':'Manual submission'} title={existing ? 'Update finding details' : 'Submit a finding'} description="Describe the finding and attach its remediation evidence in one submission. Review takes place after submission." />{!existing&&!runId&&!partialId&&submissionMode==='manual'&&<div className="mb-5"><Button type="button" secondary size="compact" disabled={busy} onClick={()=>setSubmissionMode(null)}><ArrowLeft size={14}/>Change submission method</Button></div>}{!existing&&!runId&&!partialId&&submissionMode==='report'&&<AuditReportIntake initialOpen onOpenChange={open=>{if(!open)setSubmissionMode('manual');}} />}{draft&&<Card className="mb-6 max-w-4xl">{!reportDraft&&<Link className="mb-4 inline-block text-xs font-semibold text-accent" to={'/app/submission/report/'+runId}>Back to report findings</Link>}<h2 className="font-display text-lg font-semibold">Review extracted finding</h2><p className="mt-3 text-xs leading-6">{sourceReport?.filename}. Complete missing details, choose the finding category and control scope, and check the original before creating this submission. The audit report is source context, not proof of completed remediation.</p>{sourceReport?.result?.limitations.map((note,index)=><div className="mt-3" key={index}><Notice>{note}</Notice></div>)}<a className="mt-3 inline-block text-xs font-semibold text-accent" href={sourceHref(runId)} target="_blank" rel="noopener noreferrer">Open original audit report</a><details className="mt-4"><summary className="cursor-pointer text-sm font-semibold">Proposed fields and source references</summary>{draft.sources.map((source,index)=><div key={index} className="mt-4"><p className="text-xs font-semibold">{source.field.replaceAll('_',' ')}: {draft.fields[source.field]}</p><SourceQuote source={source}/></div>)}</details>{sourceReport?.submissions?.some(item=>item.draft_index===draftIndex)&&<Notice>This draft has already been submitted. Its source cannot create another finding.</Notice>}</Card>}{(submissionMode==='manual'||!!runId||!!existing)&&<form key={runId+':'+draftIndex} onSubmit={save}><Card className="max-w-4xl"><fieldset disabled={busy||!!partialId}><div className="grid gap-5 sm:grid-cols-2"><div className="sm:col-span-2"><Field label="Finding title"><input name="title" required minLength={3} maxLength={200} defaultValue={initial.title || ''} /></Field></div><div className="sm:col-span-2"><Field label="Finding description"><textarea name="description" required minLength={10} maxLength={10000} rows={3} defaultValue={initial.description || ''} /></Field></div><Field label="Remediation owner"><input name="owner" required minLength={2} maxLength={200} defaultValue={initial.owner || ''} /></Field><Field label="Severity"><select name="severity" defaultValue={initial.severity || (runId ? '' : 'Medium')} required>{runId&&<option value="">Select finding severity</option>}{existing && !['High','Medium','Low'].includes(existing.severity) && <option value={existing.severity}>Legacy value: {existing.severity}</option>}<option>High</option><option>Medium</option><option>Low</option></select></Field><Field label="Finding category"><select name="protocol_code" value={protocolCode} onChange={e => { setProtocolCode(e.target.value); if (!existing) setScopeRequest(emptyScope()); }} required disabled={!!existing && !imported}>{runId&&<option value="">Select finding category</option>}{imported && <option value="legacy-unassigned" disabled>Select a review protocol</option>}{protocols.map(p => <option key={p.code} value={p.code}>{p.title} · {p.version}</option>)}</select></Field>{existing && !imported && <input type="hidden" name="protocol_code" value={existing.protocol_code} />}<Field label="Original audit reference (optional)"><input name="control_reference" maxLength={200} defaultValue={initial.control_reference || ''} placeholder="Original audit reference, if supplied" /></Field>{!existing && <div className="sm:col-span-2 rounded-xl border border-line p-5"><ScopeSelection category={protocolCode} value={scopeRequest} onChange={setScopeRequest}/></div>}{findingFields.map(([name, label, required]) => <div className="sm:col-span-2" key={name}><Field label={label}><textarea name={name} rows={name === 'resources' ? 3 : 2} required={required} minLength={required ? 2 : undefined} maxLength={name === 'account_reference' ? 200 : name === 'affected_systems' ? 2000 : 5000} defaultValue={initial[name] || ''} /></Field></div>)}<Field label="Implementation date (if known)"><input name="implementation_date" type="date" defaultValue={initial.implementation_date || ''} /></Field><Field label="Finding deadline (optional)"><input name="deadline" type="date" defaultValue={initial.deadline || ''} /></Field></div><div className="mt-6 space-y-4">{!existing&&<SubmissionEvidence onDraftChange={open=>{setEvidenceDraftOpen(open);if(!open)setError('');}} items={attachments} onChange={setAttachments} locked={busy||!!partialId}/>} {runId&&<><Field label="Draft confirmed by"><input name="draft_confirmed_by" required minLength={2} maxLength={200}/></Field><label className="flex gap-3 text-xs leading-6"><input type="checkbox" required checked={sourceConfirmed} onChange={e=>setSourceConfirmed(e.target.checked)}/>I checked the audit report and reviewed/corrected this draft before submission.</label></>}{error && <Notice error>{error}</Notice>}</div></fieldset><div className="mt-5 space-y-3">{progress&&<p role="status" className="text-xs leading-6">{progress}</p>}{partialId&&error&&<Link className="text-xs font-semibold text-accent" to={'/app/findings/'+partialId}>Open the saved finding</Link>}<Button disabled={busy || !protocols.length || (!existing && !previewScope(protocolCode,scopeRequest).tasks.length)}>{busy ? 'Saving…' : partialId ? 'Retry remaining evidence' : existing ? 'Save revised finding' : submitLabel ? submitLabel : attachments.length ? 'Submit finding and evidence' : 'Create finding'}</Button></div></Card></form>}</>;
}

function useFinding(id: string | undefined) {
  const { orgId } = useWorkspace();
  const [finding, setFinding] = useState<ManualFinding | null>(null); const [error, setError] = useState('');
  const load = async () => { if (!id) return; setError(''); try { const record = await manualApi.finding(id); if (record.organisationId !== orgId) throw new Error('This finding belongs to a different workspace. Select its organisation above to open it.'); setFinding(record); } catch (e) { setError(errorText(e)); } };
  useEffect(() => { setFinding(null); void load(); }, [id, orgId]);
  return { finding, setFinding, error, load };
}

export function ManualFindingDetail({ editing = false }: { editing?: boolean }) {
  const { id } = useParams(); const { finding: f, error, load } = useFinding(id); const [tab, setTab] = useState('Evidence'); const [remediationSubmitted,setRemediationSubmitted]=useState(false);
  if (!f) return error ? <Notice error>{error}</Notice> : <Loading />;
  if (editing && f.lifecycle === 'closed') return <Notice>Reopen this finding before changing its details.</Notice>;
  if (editing) return <ManualFindingCreate key={f.revision} existing={f} />;
  return <><Link className="mb-6 inline-flex items-center gap-2 text-xs text-muted" to="/app/findings"><ArrowLeft size={14} />All findings</Link><PageHeader eyebrow={`Manual finding · revision ${f.revision}`} title={f.title} description={f.description} action={<Link className={buttonClass} to={'/app/reviews/' + f.id}><ClipboardCheck size={16} />Open manual review</Link>} /><div className="mb-6 flex flex-wrap gap-3"><Badge>{workflow(f.lifecycle)}</Badge><Badge tone={f.severity === 'High' ? 'red' : 'neutral'}>{f.severity}</Badge>{f.readiness ? <StateBadge state={f.readiness} /> : <Badge>No current reviewer recommendation</Badge>}<Link className="self-center text-xs font-semibold text-accent underline" to={'/app/findings/' + f.id + '/edit'}>Edit finding</Link></div><div className="mb-6"><Notice>{disclaimer}{f.hasStaleReview && ' Earlier reviews are retained in history; changed finding/evidence revisions require fresh review.'}</Notice></div><p className="mb-5 break-words text-xs text-muted">Submission ID: {f.submissionReference||f.id} · Finding ID: {f.findingReference||f.id}</p><AuditReportSource source={f.source_report}/>{remediationSubmitted&&<div className="mb-5"><Notice>Remediation submitted for review. Your response and evidence are linked to this finding. A reviewer will assess the updates and get back to you.</Notice></div>}<div role="tablist" aria-label="Manual finding sections" className="mb-6 flex gap-2 overflow-x-auto border-b border-line">{['Evidence', 'Finding context', 'Review history', 'Timeline'].map(t => <button key={t} role="tab" aria-selected={tab === t} onClick={() => setTab(t)} className={`shrink-0 border-b-2 px-4 py-3 text-sm ${tab === t ? 'border-accent font-semibold text-accent' : 'border-transparent text-muted'}`}>{t}</button>)}</div>
    {f.currentReview?.clarification_request && <div className="mb-6"><Notice><strong>Reviewer requested clarification:</strong><p className="mt-2 whitespace-pre-wrap">{f.currentReview.clarification_request}</p></Notice></div>}{f.legacy_source && <div className="mb-6"><Notice>This finding was carried across from the earlier database. Its original fields are retained. Missing owner/scope and protocol information must be completed before a new structured review. Earlier status: {String(f.legacy_source.status || 'Not recorded')}.</Notice></div>}{tab === 'Evidence' && <div className="space-y-6">{['changes_requested','retest_pending'].includes(f.lifecycle)?<><RemediationResponse key={f.id+':'+f.cycleNumber} finding={f} onSaved={async()=>{await load();setRemediationSubmitted(true);}}/><details className="rounded-xl border border-line p-4"><summary className="cursor-pointer text-sm font-semibold">Previous assessment and report</summary><ReviewWorkflow finding={f} onSaved={load} submitter /></details></>:<ReviewWorkflow finding={f} onSaved={load} submitter />}<ReviewRequests finding={f}/><ControlScopePanel key={'submission-scope-'+f.revision} finding={f} onSaved={load} readOnly={['closed','awaiting_final_approval','changes_requested','retest_pending'].includes(f.lifecycle)}/><EvidenceLibrary finding={f} onSaved={load} />{!['closed','changes_requested','retest_pending'].includes(f.lifecycle) && <EvidenceUpload key={f.revision} finding={f} onSaved={load} />}</div>}
    {tab === 'Finding context' && <Card><dl className="grid gap-5 sm:grid-cols-2">{[['Remediation owner', f.owner], ['Source account', f.account_reference], ['Protocol version', `${f.protocol.title} · ${f.protocol.version}`], ['Control reference', f.control_reference || 'Not recorded'], ...findingFields.filter(([key]) => key !== 'account_reference').map(([key, label]) => [label, f[key] || 'Not recorded'])].map(([label, value]) => <div key={label}><dt className="text-xs text-muted">{label}</dt><dd className="mt-2 whitespace-pre-wrap text-sm leading-6">{value}</dd></div>)}</dl></Card>}
    {tab === 'Review history' && <ReviewHistory finding={f} />}{tab === 'Timeline' && <ManualTimeline id={f.id} />}</>;
}

function EvidenceUpload({ finding, onSaved }: { finding: ManualFinding; onSaved: () => Promise<void> }) {
  const fileInput = useRef<HTMLInputElement>(null); const fileId = useId();
  const [file, setFile] = useState<File | null>(null); const [error, setError] = useState(''); const [busy, setBusy] = useState(false); const w = useWorkspace();
  async function save(event: FormEvent<HTMLFormElement>) {
    event.preventDefault(); if (!file) return; const data = new FormData(event.currentTarget); const form = event.currentTarget;
    setBusy(true); setError('');
    try { await manualApi.upload(finding.id, file, { revision: finding.revision, evidence_type: text(data, 'evidence_type'), source_system: text(data, 'source_system'), source_account: text(data, 'source_account'), covered_resources: text(data, 'covered_resources'), captured_at: text(data, 'captured_at') || null, period_start: text(data, 'period_start') || null, period_end: text(data, 'period_end') || null, description: text(data, 'description'), submitted_by: text(data, 'submitted_by'), supersedes_id: text(data, 'supersedes_id') || null }); form.reset(); setFile(null); await onSaved(); await w.refresh(); }
    catch (e) { setError(errorText(e)); } finally { setBusy(false); }
  }

  return <Card><h2 className="font-display text-xl font-semibold">Upload submitted evidence</h2><p className="mt-2 mb-5 text-sm leading-6 text-muted">PDF, DOCX, PNG, JPG, CSV, JSON or TXT · 25 MB each · 30 files / 250 MB per finding. MP4 is disabled. Files are saved in shared evidence storage.</p><form onSubmit={save} className="grid gap-5 sm:grid-cols-2"><div className="sm:col-span-2"><label htmlFor={fileId} className="mb-2 block text-sm font-medium">Evidence file</label><div className="flex flex-wrap items-center gap-4 rounded-2xl border-2 border-dashed border-accent/40 bg-soft/50 p-5"><Upload size={28} className="shrink-0 text-accent" aria-hidden="true" /><div className="min-w-0 flex-1"><p className="text-sm font-semibold">Select a document to attach</p><p id={fileId + '-selection'} aria-live="polite" className="mt-1 break-all text-xs leading-6 text-muted">{file ? `${file.name} · ${file.size >= 1048576 ? (file.size / 1048576).toFixed(1) + ' MB' : Math.max(1, Math.ceil(file.size / 1024)) + ' KB'}` : 'No file selected. Click Browse files to choose your evidence.'}</p></div><Button type="button" disabled={busy} onClick={() => fileInput.current?.click()}>Browse files</Button><input id={fileId} ref={fileInput} className="sr-only" type="file" accept=".pdf,.docx,.png,.jpg,.jpeg,.csv,.json,.txt" required aria-describedby={fileId + '-selection'} onChange={e => setFile(e.target.files?.[0] || null)} /></div></div><Field label="Evidence type"><input name="evidence_type" required minLength={2} maxLength={100} placeholder="Before/after policy export, screenshot, change record…" /></Field><Field label="Submitted by"><input name="submitted_by" value="Workspace participant" readOnly /></Field><Field label="Source system"><input name="source_system" required minLength={2} maxLength={200} placeholder="e.g. application, platform or audit source" /></Field><Field label="Source account / redacted reference"><input name="source_account" required minLength={2} maxLength={200} defaultValue={finding.account_reference} /></Field><div className="sm:col-span-2"><Field label="Covered identities / resources"><textarea name="covered_resources" required minLength={2} maxLength={5000} defaultValue={finding.resources} /></Field></div><Field label="Capture date (if known)"><input name="captured_at" type="date" /></Field><Field label="Replaces evidence (optional)"><select name="supersedes_id"><option value="">New evidence</option>{finding.evidence?.filter(e => !finding.evidence?.some(next => next.supersedesId === e.id)).map(e => <option key={e.id} value={e.id}>{e.filename} · v{e.version}</option>)}</select></Field><Field label="Coverage period start (optional)"><input name="period_start" type="date" /></Field><Field label="Coverage period end (optional)"><input name="period_end" type="date" /></Field><div className="sm:col-span-2"><Field label="Evidence description"><textarea name="description" required minLength={10} maxLength={5000} rows={3} /></Field></div><div className="sm:col-span-2 space-y-4">{error && <Notice error>{error}</Notice>}<Button disabled={!file || busy}><Upload size={16} />{busy ? 'Uploading…' : 'Upload evidence'}</Button></div></form></Card>;
}

function EvidenceLibrary({ finding, onSaved }: { finding: ManualFinding; onSaved: () => Promise<void> }) {
  return <Card><h2 className="mb-4 font-display text-xl font-semibold">Submitted evidence</h2>{!finding.evidence?.length && !finding.legacyEvidence?.length ? <Empty title="No evidence submitted" description="Upload original files and source metadata for a person to inspect." /> : <div className="space-y-5">{finding.evidence?.map(e => <EvidenceCard key={e.id + e.disposition} evidence={e} finding={finding} onSaved={onSaved} />)}</div>}{!!finding.legacyEvidence?.length && <div className="mt-5 border-t border-line pt-5"><h3 className="text-sm font-semibold">Earlier evidence references</h3><p className="mt-2 text-xs leading-6 text-muted">These original records and files have not been deleted. Their size, provenance and current private-storage availability were not established by the earlier schema. Re-upload the original file here before using it in a new structured review.</p>{finding.legacyEvidence.map(e => <div className="mt-4 rounded-xl border border-line p-4" key={e.id}><p className="break-all text-sm font-semibold">{e.filename} · v{e.evidence_version ?? e.version ?? 'Not recorded'}</p><Badge>Legacy reference — not newly verified</Badge><p className="mt-2 break-all text-[10px] text-muted">Original record: {e.id}<br />Recorded SHA-256: {e.sha256 || 'Not recorded'}</p></div>)}</div>}</Card>;
}

function EvidenceCard({ evidence: e, finding }: { evidence: ManualEvidence; finding: ManualFinding; onSaved: () => Promise<void> }) {
  const [preview,setPreview]=useState(false);const closePreview=useCallback(()=>setPreview(false),[]);
  const [error,setError]=useState('');
  return <article className="rounded-xl border border-line p-4"><div className="flex flex-wrap items-start justify-between gap-3"><div className="min-w-0"><h3 className="break-all text-sm font-semibold"><FileText className="mr-2 inline text-accent" size={16} />{e.filename} · v{e.version}</h3><p className="mt-2 break-all text-xs text-muted">Evidence ID: {e.reference||e.id}</p><p className="mt-2 text-xs text-muted">{e.metadata.source_system} · {e.metadata.source_account} · {e.metadata.submitted_by}</p></div><Badge>{e.disposition}</Badge></div><p className="mt-3 whitespace-pre-wrap text-xs leading-6">{e.metadata.description}<br />Scope: {e.metadata.covered_resources}<br />Captured: {e.metadata.captured_at || 'Unknown'} · Period: {e.metadata.period_start || 'Unknown'} — {e.metadata.period_end || 'Unknown'}</p><p className="mt-2 break-all font-mono text-[10px] text-muted">SHA-256 {e.sha256}</p><p className="mt-2 text-[11px] text-amber-800">{e.scanStatus}</p><div className="mt-4 flex flex-wrap gap-3"><Button secondary type="button" onClick={()=>setPreview(true)}>{preview ? 'Hide inspection' : 'Inspect evidence'}</Button><Button secondary type="button" onClick={() => { manualApi.download(finding.id, e.id).catch(error => setError(errorText(error))); }}><Download size={15} />Download original</Button></div>{preview&&<EvidencePreview findingId={finding.id} evidence={e} onClose={closePreview}/>}
    {error && <div className="mt-4"><Notice error>{error}</Notice></div>}</article>;
}

export function ManualReviewWorkspace() {
  const { id } = useParams(); const { finding, error, load } = useFinding(id); const w = useWorkspace(); const [supersedes, setSupersedes] = useState<string | null>(null);
  const [reviewParams] = useSearchParams();
  const requestedAssessment = reviewParams.get('assessment');
  useEffect(() => {
    const assessment = finding?.reviews?.find(review => review.id === requestedAssessment && review.status === 'completed' && !review.stale && review.cycleNumber === finding.cycleNumber);
    setSupersedes(finding?.lifecycle === 'review_completed' && assessment ? assessment.id : null);
  }, [finding?.id, finding?.revision, finding?.lifecycle, requestedAssessment]);
  if (!finding) return error ? <Notice error>{error}</Notice> : <Loading />;
  if (!finding.protocol.checks.length) return <><PageHeader title="Select a review protocol" description="The earlier record has no pinned structured checklist. The submitter or an admin must complete its details and choose a protocol before review." /><Link className={secondaryClass} to={'/app/findings/' + finding.id + '/edit'}>Complete finding details</Link></>;

  const completed = finding.reviews?.some(review => review.status === 'completed' && review.cycleNumber === finding.cycleNumber);
  return <><Link className="mb-6 inline-flex items-center gap-2 text-xs text-muted" to="/app/reviews"><ArrowLeft size={14} />Back to reviewer queue</Link><PageHeader title="Inspect. Record. Explain." description={finding.title} /><div className="space-y-6"><details className="rounded-2xl border border-line bg-white p-5"><summary className="cursor-pointer text-sm font-semibold">Submitted finding and evidence</summary><div className="mt-5 grid gap-6 lg:grid-cols-2"><Card><h2 className="font-display text-xl font-semibold">Finding context</h2><p className="mt-3 whitespace-pre-wrap text-sm leading-6">{finding.description}</p><dl className="mt-5 space-y-4 text-xs">{[['Remediation owner', finding.owner], ['Control reference', finding.control_reference], ['Implementation date', finding.implementation_date], ['Finding deadline', finding.deadline], ['Account', finding.account_reference], ['Affected resources', finding.resources], ['Baseline', finding.approved_baseline], ['Root cause', finding.root_cause], ['Corrective action', finding.corrective_action], ['Recurrence prevention', finding.recurrence_prevention]].map(([label, value]) => <div key={label}><dt className="font-semibold">{label}</dt><dd className="mt-1 whitespace-pre-wrap leading-6 text-muted">{value || 'Not recorded — request clarification if needed.'}</dd></div>)}</dl></Card></div></details><p className="break-words text-xs text-muted">Submission ID: {finding.submissionReference||finding.id} · Finding ID: {finding.findingReference||finding.id}</p><AuditReportSource source={finding.source_report}/><ReviewWorkflow finding={finding} onSaved={load} onRevise={setSupersedes} reviewer /><ControlScopePanel key={'control-scope-'+finding.revision} finding={finding} onSaved={load} readOnly/><ReviewRequests finding={finding} reviewer/>{(!completed || supersedes) && finding.lifecycle !== 'closed' && finding.lifecycle !== 'awaiting_final_approval' && <><ManualChecklist key={finding.revision + ':' + (supersedes || '')} finding={finding} onSaved={load} onCompleted={() => setSupersedes(null)} supersedes={supersedes} /></>}</div></>;
}

export function ManualChecklist({ finding, onSaved, supersedes = null, onCompleted }: { finding: ManualFinding; onSaved: () => Promise<void>; supersedes?: string | null; onCompleted?: () => void }) {
  const current = supersedes
    ? finding.reviews?.find(r => !r.stale && r.status === 'saved' && r.supersedesId === supersedes) || finding.reviews?.find(r => r.id === supersedes)
    : finding.reviews?.find(r => !r.stale && r.cycleNumber === finding.cycleNumber);
  const reviewForm=useRef<HTMLFormElement>(null);
  const [proposal,setProposal]=useState<ReviewProposal|null>(null);
  const [appliedProposal,setAppliedProposal]=useState<AppliedReviewProposal|undefined>(current?.ai_review_proposal);
  const [proposalSourceKeys,setProposalSourceKeys]=useState(current?.ai_review_source_keys||current?.ai_review_proposal_snapshot?.source_keys||[]);
  const [preparing,setPreparing]=useState(false);const [preparationFailed,setPreparationFailed]=useState(false);const [preparationProgress,setPreparationProgress]=useState('');
  const proposalRequest=useRef(crypto.randomUUID());

  const [engineEnabled,setEngineEnabled]=useState(!!assessmentMethod(finding.protocol.code)&&!!current?.engine_draft);
  const [engineDraft,setEngineDraft]=useState<EngineDraft>(assessmentMethod(finding.protocol.code)?restoreEditableEngineDraft(newProtocolDraft(finding.protocol.code,current?.engine_draft),current?.review_shared_sources):{version:'0.2.0-checklist-candidate',entries:{}});
  const [engineSelection,setEngineSelection]=useState<EngineRequest>({draft:engineDraft,evaluationHash:'',disposition:'',overrideReason:'',overrideEvidenceIds:[]});
  const [enginePreview,setEnginePreview]=useState<EnginePreview|null>(null);
  const evidenceAnalysis = useRef<EvidenceAnalysisHandle>(null);
  const [aiConfirmationIds,setAiConfirmationIds]=useState<string[]>(current?.ai_confirmation_ids||[]);
  const sections = activeSections(finding.protocol,{version:JUDGEMENT_VERSION});
  const includesModule = (id: string) => sections.some(section => section.id === id);
  const [reviewSources,setReviewSources] = useState(current?.review_shared_sources || {...emptyReviewSources(),enabled:!current?.engine_draft});
  const [conclusion,setConclusion] = useState(combinedReviewConclusion(current?.reviewer_conclusion,current?.closure_judgement?.established_facts,current?.recommendation_reason));
  const [scopeConfirmed,setScopeConfirmed] = useState(!!current?.scope_confirmed);
  const [judgement, setJudgementState] = useState<ClosureJudgement>(()=>({...upgradeJudgement(current?.closure_judgement),remaining_actions:combinedReviewConclusion(current?.closure_judgement?.remaining_actions,current?.clarification_request),...(current && current.closure_judgement?.version!==JUDGEMENT_VERSION ? {exceptions_status:current.exception_entries?.length?'Exceptions identified':current.exceptions_assessed?'None identified':undefined}: {})}));
  const [checks, setChecks] = useState<ManualCheck[]>((current?.checks || finding.protocol.checks.map(c => ({ check_id: c.id, result: 'unknown' as const, reason: '', evidence_ids: [], source_location: '' }))).map(check => initialiseSoaCheck(check)));
  const [recommendation, setRecommendation] = useState<Readiness | ''>(current?.recommendation || ''); const [independent, setIndependent] = useState(current?.independent || false);
  const [busy, setBusy] = useState(false); const [error, setError] = useState(''); const [saved, setSaved] = useState(''); const w = useWorkspace();
  const stepTitles = ['Evidence & checklist', 'Gaps & exceptions', 'Recommendation & report'];
  const [step,setStep] = useState(current?.status === 'saved' && !supersedes && [0,1,2].includes(current.review_step ?? -1) ? current.review_step! : 0);
  const headingRef = useRef<HTMLHeadingElement>(null);
  const stepId = useId();
  useEffect(() => {
    if (!supersedes) return;
    const frame = requestAnimationFrame(() => {
      headingRef.current?.focus({preventScroll:true});
      headingRef.current?.scrollIntoView({block:'start',behavior:'smooth'});
    });
    return () => cancelAnimationFrame(frame);
  }, [supersedes]);
  function goToStep(next: number, clearFeedback = true) {
    setStep(next);
    if (clearFeedback) { setError(''); setSaved(''); }
    requestAnimationFrame(() => { const active=document.activeElement; if(active instanceof HTMLElement && active.matches('input,textarea,select') && !active.closest('[hidden]'))return; headingRef.current?.focus({preventScroll:true}); headingRef.current?.scrollIntoView({block:'start'}); });
  }
  function fail(message: string, target: number) { setError(message); setBusy(false); goToStep(target,false); }

  const [unassessedReason,setUnassessedReason] = useState(current?.unassessed_checks_reason || '');
  const completionRequest = useRef(crypto.randomUUID());
  const [exceptionEntries, setExceptionEntries] = useState<ExceptionEntry[]>(current?.exception_entries || []);
  const [populationExpected,setPopulationExpectedState]=useState(String(current?.population_expected??''));
  const [populationReviewed,setPopulationReviewedState]=useState(String(current?.population_reviewed??''));
  function invalidateCoverage(){if(appliedProposal)setEngineDraft(previous=>({...previous,entries:{...previous.entries,...(previous.entries.coverage?{coverage:{...previous.entries.coverage,value:''}}:{})}}));setEnginePreview(null);setEngineSelection(value=>({...value,evaluationHash:'',disposition:''}));}
  function setPopulationExpected(value:string){setPopulationExpectedState(value);invalidateCoverage();}
  function setPopulationReviewed(value:string){setPopulationReviewedState(value);invalidateCoverage();}
  const currentEvidenceIds=(finding.evidence||[]).filter(file=>!finding.evidence?.some(next=>next.supersedesId===file.id)&&!['rejected','insufficient'].includes(file.disposition)).map(file=>file.id);
  const reusedAssessment=reuseReviewInputs(engineDraft,judgement,reviewSources,sections.map(section=>section.id),currentEvidenceIds,{confirmed:scopeConfirmed,exclusions:finding.protocol.review_scope?.module_exclusions||{}});
  const effectiveEngineDraft=reusedAssessment.draft;
  function showAssessmentSourceIssue(issue:AssessmentSourceIssue) {
    const shared=!!reusedAssessment.reused[issue.fieldId]||reusedAssessment.inheritedSources.includes(issue.fieldId);
    setError(assessmentSourceMessage(issue,shared));goToStep(1,false);
    requestAnimationFrame(()=>{
      const active=document.activeElement;
      if(active instanceof HTMLElement&&active.matches('input,textarea,select')&&!active.closest('[hidden]'))return;
      const form=headingRef.current?.closest('section')?.querySelector('[data-review-form]');
      const area=shared?form?.querySelector('[data-review-sources]'):Array.from(form?.querySelectorAll<HTMLElement>('[data-engine-field]')||[]).find(element=>element.dataset.engineField===issue.fieldId);
      if(!area)return;
      area.querySelectorAll('details').forEach(details=>{details.open=true;});
      const target=shared?area.querySelector<HTMLElement>(`[data-source-input="${issue.missing[0]}"]`):issue.missing[0]==='basis'?area.querySelector<HTMLElement>('textarea'):issue.missing[0]==='locator'?area.querySelector<HTMLElement>('input:not([type="checkbox"])'):area.querySelector<HTMLElement>('input[type="checkbox"]');
      (target||area).scrollIntoView({block:'center'});target?.focus({preventScroll:true});
    });
  }
  const assessmentSignature=JSON.stringify(effectiveEngineDraft);
  useEffect(()=>{setEnginePreview(null);setEngineSelection(value=>({...value,evaluationHash:'',disposition:''}));},[assessmentSignature]);
  function setJudgement(update:Parameters<typeof setJudgementState>[0]) {
    const next=typeof update==='function'?update(judgement):update;
    setJudgementState(next);
    const substantive=Object.keys({...judgement,...next}).some(key=>key!=='closure_ready_acknowledged'&&JSON.stringify(next[key as keyof ClosureJudgement])!==JSON.stringify(judgement[key as keyof ClosureJudgement]));
    if(substantive){setEnginePreview(null);setEngineSelection(value=>({...value,evaluationHash:'',disposition:''}));}
    if(appliedProposal)setEngineDraft(previous=>{
      const entries={...previous.entries};
      const sync=(id:string,value:string)=>{if(entries[id])entries[id]={...entries[id],value};};
      if(next.scope_status!==judgement.scope_status){sync('scope',next.scope_status==='Sufficient for this finding'?'true':'');sync('evidence',next.scope_status==='Sufficient for this finding'?'true':'');}
      if(next.cause_status!==judgement.cause_status)sync('cause',next.cause_status==='Supported'?'true':'');
      if(next.exceptions_status!==judgement.exceptions_status)sync('exceptions',next.exceptions_status==='None identified'?'true':'');
      for(const module of ['operation','retest'] as const)if(next[(module+'_requirement') as keyof ClosureJudgement]!==judgement[(module+'_requirement') as keyof ClosureJudgement])sync(module+'_required',next[(module+'_requirement') as keyof ClosureJudgement]==='Required'?'true':next[(module+'_requirement') as keyof ClosureJudgement]==='Not required'?'false':'');
      for(const [id,key]of [['operation_start','operating_from'],['operation_end','operating_to'],['required_cycles','expected_cycles'],['observed_cycles','observed_cycles']] as const)if(next[key]!==judgement[key])sync(id,next[key]||'');
      if(next.retest_status!==judgement.retest_status)sync('retest',['Planned','Not performed'].includes(next.retest_status||'')?'pending':'');
      return {...previous,entries};
    });
  }
  function change(id: string, patch: Partial<ManualCheck>) { setEnginePreview(null);setEngineSelection(value=>({...value,evaluationHash:'',disposition:''}));setChecks(list => list.map(c => c.check_id === id ? { ...c, ...patch, ...('reason' in patch ? { reason_source: undefined } : {}), ...(c.reason_source === 'shared_unassessed_note' && patch.implementation_status && patch.implementation_status !== 'not_assessed' ? { reason: '', reason_source: undefined } : {}) } : c)); }
  async function save(event: FormEvent<HTMLFormElement>) {
    event.preventDefault(); const publish = (event.nativeEvent as SubmitEvent).submitter?.getAttribute('data-review-action') === 'complete'; setError(''); setSaved(''); setBusy(true); const data = new FormData(event.currentTarget);
    const completedAnswers = { ...judgement, established_facts: conclusion };
    const followup = judgement.followup_status==='None required'?'':judgement.remaining_actions||current?.clarification_request||'';
    const body: ReviewInput = { ...(appliedProposal?{ai_review_proposal:appliedProposal,ai_review_source_keys:proposalSourceKeys}:{}),streamlined_review:true, ...(engineEnabled?{review_shared_sources:{...reviewSources,fieldIds:Object.keys(reusedAssessment.reused),sourceFieldIds:reusedAssessment.inheritedSources},engine_draft:effectiveEngineDraft,...(publish?{engine_request:{...engineSelection,draft:effectiveEngineDraft}}:{})}:{}), ai_confirmation_ids: aiConfirmationIds, review_step: step, unassessed_checks_reason: unassessedReason, scope_confirmed: scopeConfirmed, scope_confirmation_notes: text(data,'scope_confirmation_notes'), reviewer_conclusion: conclusion, supersedes_assessment_id: supersedes, exception_entries: publish&&judgement.exceptions_status!=='Exceptions identified'?[]:exceptionEntries, exceptions_assessed:['None identified','Exceptions identified'].includes(judgement.exceptions_status||''), closure_judgement: { ...completedAnswers, version: JUDGEMENT_VERSION }, revision: finding.revision, reviewer: text(data, 'reviewer'), independent, independence_notes: text(data, 'independence_notes'), checks,
      population_expected: populationExpected===''||publish&&!judgementRequirement(judgement,'population')?null:Number(populationExpected), population_reviewed: populationReviewed===''||publish&&!judgementRequirement(judgement,'population')?null:Number(populationReviewed), population_notes: '',
      exceptions: '', operating_period_notes: '', retest_notes: '', clarification_request: followup,
      recommendation: recommendation || null, recommendation_reason: conclusion, next_status: 'under_review', publish: false };
    const soaError = validateSoaChecks(checks, publish);
    if (soaError) { fail(soaError,0); return; }
    if (publish) {
      if(engineEnabled&&reviewSources.enabled&&(reviewSources.basis.trim().length<10||reviewSources.locator.trim().length<2||!reviewSources.evidenceIds.length||reviewSources.evidenceIds.some(id=>!currentEvidenceIds.includes(id)))){fail('Record the shared assessment basis, source location and current supporting evidence.',1);return;}
      if(engineEnabled&&(!enginePreview?.evaluation.recommendation||!engineSelection.evaluationHash||!engineSelection.disposition)){fail('Evaluate readiness and accept or override its recommendation before completing.',2);return;}
      const invalid = Array.from(event.currentTarget.querySelectorAll<HTMLInputElement | HTMLTextAreaElement | HTMLSelectElement>('input,textarea,select')).find(field => field.willValidate && !field.checkValidity());
      if (invalid) { const target = Number(invalid.closest('[data-review-step]')?.getAttribute('data-review-step') || 0); fail(`Check the highlighted field: ${invalid.validationMessage}`,target); requestAnimationFrame(() => { invalid.focus(); invalid.reportValidity(); }); return; }
      const prepared = prepareCompletionChecks(checks,unassessedReason);
      if (prepared.error) { fail(prepared.error,0); return; }
      body.checks = prepared.checks;
      if (finding.protocol.review_scope && !scopeConfirmed) { fail('Confirm the review scope before completion.',0); return; }
      if (recommendation === 'Ready for retest' && !includesModule('retest')) { fail('Amend the review scope to include retest assessment before recommending Ready for retest. Save your draft first.',2); return; }
      if (recommendation==='Ready for retest' && includesModule('retest') && judgement.retest_requirement!=='Required') { fail('Select Required for the independent retest assessment before recommending Ready for retest.',1); return; }
      if (['Not closure ready','Implemented but evidence incomplete','Ready for retest'].includes(recommendation)&&followup.trim().length<10) { fail('Record the required next actions and evidence requests for this recommendation.',2); return; }
      if(conclusion.length>2000){fail('Keep the review conclusion and rationale within 2,000 characters. Earlier draft notes remain in review history.',2);return;}
      if ((body.reviewer_conclusion || '').length < 10) { fail('Enter your reviewer conclusion.',2); return; }
      if (judgement.exceptions_status==='Exceptions identified' && exceptionEntries.length===0) { fail('Add the identified exceptions, or change the exception decision.',1); return; }
      const judgementError=validateJudgement(completedAnswers,sections,body.exception_entries?.length||0);
      if(judgementError){fail(judgementError.message,judgementError.step);return;}
      if (judgementRequirement(judgement,'retest') && judgement.retest_status === 'Completed' && !judgement.retest_evidence_id) { fail('Link the completed retest to submitted evidence.',1); return; }
      for (const entry of body.exception_entries || []) {
        if (entry.disposition === 'accepted' && (!entry.acceptance_authority?.trim() || !entry.acceptance_date || !entry.acceptance_reference?.trim())) { fail('Record who accepted the exception, the decision date and its supporting reference.',1); return; }
        if (entry.disposition === 'mitigated' && (entry.compensating_controls||'').trim().length<10) { fail('Describe the compensating controls for each mitigated exception.',1); return; }
      }
      body.closure_judgement = completedJudgement(completedAnswers,sections,body.exception_entries?.length||0);
      if (judgementRequirement(judgement,'retest') && judgement.retest_status === 'Completed' && (!judgement.retester?.trim() || !judgement.retest_date)) { fail('Record who performed the completed retest and its date.',1); return; }
      if (recommendation === 'Closure ready' && !judgement.closure_ready_acknowledged) { fail('Confirm that you have explained unresolved observations and the basis for your closure-ready recommendation.',2); return; }
    }
    try { body.ai_confirmation_ids = await evidenceAnalysis.current!.saveFacts(body.reviewer,appliedProposal?proposalSourceKeys:undefined); if (publish) { await workflowApi.complete(finding.id, finding.revision, body, completionRequest.current, supersedes); setSaved('Review completed. The assessment is saved and its report is pending.'); onCompleted?.(); } else { await manualApi.saveReview(finding.id, body); setSaved('Manual review draft saved. No readiness recommendation was published.'); } await onSaved(); await w.refresh(); } catch (e) { setError(errorText(e)); } finally { setBusy(false); }
  }
  async function prepareFromEvidence(){
    const reviewer=reviewForm.current?.querySelector<HTMLInputElement>('[name="reviewer"]')?.value.trim()||'';
    if(reviewer.length<2){fail('Enter the reviewer name before preparing the review.',0);return;}
    setBusy(true);setPreparing(true);setPreparationFailed(false);setError('');setSaved('');setProposal(null);
    try{
      const files=(finding.evidence||[]).filter(file=>/\.(pdf|docx)$/i.test(file.filename)&&currentEvidenceIds.includes(file.id));
      if(!files.length)throw Error('Upload PDF or DOCX remediation evidence on the finding before preparing the review.');
      const existing=await documentApi.list(finding.id);
      for(let i=0;i<files.length;i++){
        const file=files[i];if(existing.runs.some(run=>run.status==='ready'&&run.finding_revision===finding.revision&&run.evidence_id===file.id&&run.evidence_version===file.version&&run.sha256===file.sha256))continue;
        setPreparationProgress(`Reading evidence ${i+1} of ${files.length}: ${file.filename}`);
        const {run}=await documentApi.evidence(finding.id,finding.revision,file.id,crypto.randomUUID());await documentApi.process(run.id);
      }
      setPreparationProgress('Preparing checklist answers, review judgements and assessment sources…');
      await evidenceAnalysis.current!.saveEdits(reviewer);
      const result=await enginePost<ReviewProposal>('propose',{findingId:finding.id,revision:finding.revision,requestId:proposalRequest.current});setProposal(result);proposalRequest.current=crypto.randomUUID();setPreparationProgress('');
    }catch(e){setPreparationFailed(true);setError(errorText(e));setPreparationProgress('');proposalRequest.current=crypto.randomUUID();}finally{setBusy(false);setPreparing(false);}
  }
  async function applyPreparedReview(){
    if(!proposal)return;const reviewer=reviewForm.current?.querySelector<HTMLInputElement>('[name="reviewer"]')?.value.trim()||'';
    if(reviewer.length<2){fail('Enter the reviewer name before using the prepared review.',0);return;}
    const prepared=proposal.prepared;
    setChecks(prepared.checks);setJudgement({...prepared.judgement,remaining_actions:prepared.nextActions});setExceptionEntries(prepared.exceptions);
    setPopulationExpectedState(prepared.expected===null?'':String(prepared.expected));setPopulationReviewedState(prepared.reviewed===null?'':String(prepared.reviewed));setConclusion(prepared.conclusion);
    setEngineDraft(prepared.engine);setEngineEnabled(true);setReviewSources(emptyReviewSources());setUnassessedReason('The supplied evidence does not establish the unassessed items. Follow the recorded evidence requests.');
    setAppliedProposal({id:proposal.id,source_fingerprint:proposal.source_fingerprint,reviewer,applied_at:new Date().toISOString()});setProposalSourceKeys(prepared.sourceKeys);setRecommendation('');setEnginePreview(null);setEngineSelection(value=>({...value,evaluationHash:'',disposition:''}));setSaved('Prepared answers are in the review. Check or edit them. Missing information remains unresolved.');goToStep(1,false);
    setBusy(true);
    try{const result=await enginePost<EnginePreview>('evaluate',{findingId:finding.id,revision:finding.revision,reviewer,draft:prepared.engine,checks:prepared.checks});setEnginePreview(result);setEngineSelection(value=>({...value,draft:prepared.engine,evaluationHash:result.evaluationHash,disposition:''}));}catch(e){setError('The draft is populated, but readiness needs attention: '+errorText(e));}finally{setBusy(false);}
  }
  const renderExceptionRecords = () => <fieldset className="rounded-xl border border-line p-5"><legend className="px-2 font-semibold">Exception records</legend>{exceptionEntries.map((entry, index) => <div key={index} className="mt-5 grid gap-4 border-t border-line pt-5 sm:grid-cols-2">{(['reference','description','owner','evidence_reference','closure_impact'] as const).map(key => <Field key={key} label={`Exception ${index + 1}: ${key.replaceAll('_', ' ')}`}><input value={entry[key]} maxLength={2000} onChange={e => setExceptionEntries(entries => entries.map((item, i) => i === index ? { ...item, [key]: e.target.value } : item))} /></Field>)}<Field label={`Exception ${index + 1}: disposition`}><select value={entry.disposition} onChange={e => setExceptionEntries(entries => entries.map((item, i) => i === index ? { ...item, disposition: e.target.value as ExceptionEntry['disposition'] } : item))}><option value="open">Open</option><option value="resolved">Resolved</option><option value="accepted">Accepted</option><option value="mitigated">Mitigated</option></select></Field>{entry.disposition === 'accepted' && <>{(['acceptance_authority','acceptance_date','acceptance_reference'] as const).map(key=><Field key={key} label={`Exception ${index+1}: ${key.replaceAll('_',' ')}`}><input type={key==='acceptance_date'?'date':'text'} maxLength={2000} value={entry[key]||''} onChange={e=>setExceptionEntries(entries=>entries.map((item,i)=>i===index?{...item,[key]:e.target.value}:item))}/></Field>)}<p className="text-xs leading-6 text-muted sm:col-span-2">Record the actual acceptance decision and authority; choosing Accepted does not grant approval.</p></>}{entry.disposition === 'mitigated' && <div className="sm:col-span-2"><Field label={`Exception ${index+1}: compensating controls`}><textarea rows={3} maxLength={2000} value={entry.compensating_controls||''} onChange={e=>setExceptionEntries(entries=>entries.map((item,i)=>i===index?{...item,compensating_controls:e.target.value}:item))}/></Field></div>}<Button secondary size="compact" tone="danger" type="button" onClick={() => { setExceptionEntries(entries => entries.filter((_, i) => i !== index)); }}>Remove exception {index + 1}</Button></div>)}<Button secondary className="mt-4" type="button" onClick={() => { setExceptionEntries(entries => [...entries, { reference: '', description: '', owner: '', disposition: 'open', evidence_reference: '', closure_impact: '' }]); }}>Add exception</Button></fieldset>;
  const renderJudgementSection = (section: typeof sections[number]) => {
    const fields=judgementFields(section,judgement,judgement.exceptions_status==='Exceptions identified'?exceptionEntries.length:0).filter(field=>field.key!=='established_facts');
    const hasDetails=section.id==='population'?judgementRequirement(judgement,'population')&&!!judgement.coverage_approach:section.id==='operation'||section.id==='retest'?judgementRequirement(judgement,section.id):section.id==='scope'?!!judgement.scope_status:section.id==='cause'?!!judgement.cause_status:true;
    const input=(field:typeof fields[number])=><Field label={field.label}>{field.options?<select value={field.key==='remaining_actions'?(judgement.remaining_actions??current?.clarification_request??''):judgement[field.key]||''} onChange={e=>setJudgement(j=>({...j,[field.key]:e.target.value}))}><option value="">Select reviewer assessment</option>{field.options.map(option=><option key={option}>{option}</option>)}</select>:field.type?<input type={field.type} min={field.type==='number'?0:undefined} step={field.type==='number'?1:undefined} maxLength={200} value={field.key==='remaining_actions'?(judgement.remaining_actions??current?.clarification_request??''):judgement[field.key]||''} onChange={e=>setJudgement(j=>({...j,[field.key]:e.target.value}))}/>:<textarea rows={3} maxLength={2000} placeholder={field.placeholder} value={field.key==='remaining_actions'?(judgement.remaining_actions??current?.clarification_request??''):judgement[field.key]||''} onChange={e=>setJudgement(j=>({...j,[field.key]:e.target.value}))}/>}</Field>;
    return <fieldset id={'judgement-'+section.id} key={section.id} className="scroll-mt-6 space-y-4 rounded-2xl border border-line p-5">
      <legend className="px-2 font-semibold">{section.title}</legend><p className="text-xs leading-6 text-muted">{section.description}</p>
      <div className="grid gap-5 sm:grid-cols-2">{fields.map(field=><div key={field.key} className={field.type?'':'sm:col-span-2'}>{field.required===false?<details><summary className="cursor-pointer text-xs font-semibold text-accent">{field.label}</summary><div className="mt-3">{input(field)}</div></details>:input(field)}</div>)}</div>
      {section.id==='exceptions'&&judgement.exceptions_status==='Exceptions identified'&&renderExceptionRecords()}
      {section.id==='population'&&hasDetails&&<div className="grid gap-4 sm:grid-cols-2"><Field label="Expected population"><input name="population_expected" type="number" min={0} step={1} placeholder="Unknown" value={populationExpected} onChange={e=>setPopulationExpected(e.target.value)}/></Field><Field label="Reviewed population"><input name="population_reviewed" type="number" min={0} step={1} placeholder="Unknown" value={populationReviewed} onChange={e=>setPopulationReviewed(e.target.value)}/></Field></div>}
      {section.id==='retest'&&judgementRequirement(judgement,'retest')&&judgement.retest_status==='Completed'&&<Field label="Retest evidence reference"><select value={judgement.retest_evidence_id||''} onChange={e=>setJudgement(j=>({...j,retest_evidence_id:e.target.value}))}><option value="">Select submitted retest evidence</option>{finding.evidence?.map(file=><option key={file.id} value={file.id}>{file.filename} · v{file.version}</option>)}</select></Field>}
      {hasDetails&&['scope','cause','population','operation'].includes(section.id)&&!!finding.evidence?.length&&<details className="border-t border-line pt-4"><summary className="cursor-pointer text-xs font-semibold text-accent">Evidence supporting this judgement</summary><div className="mt-3 space-y-2">{finding.evidence.map(file=><label key={file.id} className="flex items-start gap-3 text-xs leading-6"><input type="checkbox" className="mt-1" checked={!!judgement.evidence_refs?.[section.id]?.includes(file.id)} onChange={e=>setJudgement(j=>({...j,evidence_refs:{...j.evidence_refs,[section.id]:e.target.checked?[...(j.evidence_refs?.[section.id]||[]),file.id]:(j.evidence_refs?.[section.id]||[]).filter(id=>id!==file.id)}}))}/><span>{file.filename} · v{file.version}</span></label>)}</div></details>}
    </fieldset>;
  };

  return <Card>{supersedes&&<Notice>Editing a revision of the completed assessment. Existing answers are loaded below. Completing this review saves a new version and preserves the original assessment and report.</Notice>}<p className="mb-2 font-mono text-[10px] text-accent">{finding.protocol.code} · {finding.protocol.version}</p><h2 ref={headingRef} tabIndex={-1} className="scroll-mt-6 font-display text-xl font-semibold focus:outline-none">{stepTitles[step]}</h2><p className="mt-2 mb-5 text-xs leading-6 text-muted">Step {step+1} of 3 · Move between steps without losing your entries. Complete Review is available on the final step.</p><nav aria-label="Review steps" className="mb-6"><ol className="grid gap-2 sm:grid-cols-3">{stepTitles.map((title,index)=><li key={title}><button id={stepId+'-step-'+index} type="button" aria-current={step===index?'step':undefined} aria-controls={stepId+'-panel-'+index} disabled={busy} onClick={()=>goToStep(index)} className={`flex h-full w-full items-start gap-3 rounded-xl border p-3 text-left text-xs leading-6 transition-colors ${step===index?'border-accent bg-soft font-semibold text-accent':'border-line bg-white text-muted hover:border-accent/40'}`}><span>{title}</span></button></li>)}</ol></nav><div hidden={step!==0} className="mb-5 space-y-5"><EvidenceLibrary finding={finding} onSaved={onSaved}/><EvidenceAnalysis ref={evidenceAnalysis} includedKeys={appliedProposal?proposalSourceKeys:undefined} disabled={busy} finding={finding} selected={aiConfirmationIds} onChange={setAiConfirmationIds}/></div><form ref={reviewForm} data-review-form noValidate onSubmit={save} className="space-y-5">{assessmentMethod(finding.protocol.code)&&<Field label="Assessment method"><select disabled={busy} value={engineEnabled?'rules':'manual'} onChange={e=>{setEngineEnabled(e.target.value==='rules');setEnginePreview(null);setEngineSelection(value=>({...value,disposition:'',evaluationHash:''}));}}><option value="manual">Manual recommendation</option><option value="rules">Rules-supported {assessmentMethod(finding.protocol.code)?.protocol.title} assessment</option></select></Field>}{error && <Notice error>{error}</Notice>}{saved && <Notice>{saved}</Notice>}<section id={stepId+'-panel-0'} data-review-step="0" aria-labelledby={stepId+'-step-0'} hidden={step!==0} className="space-y-5"><p className="text-xs leading-6 text-muted">Assess the selected checklist against submitted evidence. Record applicability, implementation status and supporting references. Untouched checks stay Under review / Not assessed.</p><Field label="Reviewer"><input name="reviewer" required minLength={2} maxLength={200} placeholder="Reviewer name" defaultValue={current?.reviewer} /></Field>{finding.protocol.review_scope && <div className="space-y-3 rounded-xl border border-line p-4"><label className="flex items-start gap-3 text-xs leading-6"><input type="checkbox" className="mt-1" checked={scopeConfirmed} onChange={e=>setScopeConfirmed(e.target.checked)}/>I confirm that the selected controls, checklist items, review sections and exclusions are appropriate for this finding.</label><Field label={finding.protocol.review_scope.provisional?'Custom scope confirmation and justification':'Scope confirmation notes (optional)'}><textarea name="scope_confirmation_notes" required={finding.protocol.review_scope.provisional} minLength={finding.protocol.review_scope.provisional?10:undefined} maxLength={2000} defaultValue={current?.scope_confirmation_notes||''}/></Field></div>}
    {assessmentMethod(finding.protocol.code)&&<section className="space-y-4 rounded-xl border border-accent/30 bg-soft/30 p-4"><h3 className="text-sm font-semibold">Prepare review from evidence</h3><p className="text-xs leading-6 text-muted">Read the uploaded PDF/DOCX evidence and prepare cited checklist answers, gaps and engine inputs. Review the draft and correct anything needed before evaluation.</p><Button type="button" disabled={busy} onClick={()=>{void prepareFromEvidence();}}>{preparing?'Preparing review…':'Prepare review from evidence'}</Button>{preparationProgress&&<p role="status" className="text-xs leading-6">{preparationProgress}</p>}{proposal&&<PreparedReviewSummary proposal={proposal} finding={finding} disabled={busy} onApply={()=>{void applyPreparedReview();}}/>}</section>}
    {finding.protocol.checks.map(p => { const c = checks.find(c => c.check_id === p.id)!; return <fieldset data-protocol-check key={p.id} className="rounded-xl border border-line p-4"><legend className="px-2 text-sm font-semibold">{p.label}</legend><p className="mb-4 text-xs leading-6 text-muted">{p.guidance}</p>{p.mapped_controls && <p className="mb-3 text-xs text-accent">Included for: {p.mapped_controls.join(', ') || 'Additional or provisional scope'}</p>}{p.sourceTask && <ChecklistSource task={p.sourceTask} />}<div className="space-y-4"><div className="grid gap-4 sm:grid-cols-2"><Field label={`${p.label}: applicability`}><select value={c.applicability || 'under_review'} onChange={e => change(p.id, { applicability: e.target.value as SoaApplicability })}>{soaApplicabilityOptions.map(option => <option key={option.value} value={option.value}>{option.label}</option>)}</select></Field><Field label={`${p.label}: implementation status`}><select value={c.implementation_status || 'not_assessed'} onChange={e => { const status = e.target.value as SoaImplementation; change(p.id, { implementation_status: status, result: storageResult(status) }); }}>{soaImplementationOptions.map(option => <option key={option.value} value={option.value}>{option.label}</option>)}</select></Field></div><Field label={`${p.label}: rationale`}><textarea rows={2} maxLength={5000} value={c.reason} onChange={e => change(p.id, { reason: e.target.value })} /></Field><Field label={`${p.label}: source location`}><input maxLength={1000} value={c.source_location} onChange={e => change(p.id, { source_location: e.target.value })} placeholder={appliedProposal?'No supporting source identified for this item':'Prepare review from evidence to populate this reference, or enter it manually'} /></Field>{!c.source_location&&<p className="text-xs leading-6 text-muted">{preparationFailed?'Review preparation did not complete, so this reference has not been populated. Retry preparation or enter a checked source reference.':appliedProposal?'No supporting citation was identified for this checklist item. Keep it Not assessed unless you can link and cite relevant evidence.':'A source reference appears after you prepare and use the review draft. Uploading or extracting a document alone does not populate this checklist.'}</p>}<div><p className="mb-2 text-xs font-semibold">Linked evidence</p>{finding.evidence?.length ? finding.evidence.map(e => <label key={e.id} className="my-2 flex items-start gap-2 text-xs leading-5"><input type="checkbox" checked={c.evidence_ids.includes(e.id)} onChange={event => change(p.id, { evidence_ids: event.target.checked ? [...c.evidence_ids, e.id] : c.evidence_ids.filter(id => id !== e.id) })} /><span>{e.filename} · v{e.version} · {e.disposition}</span></label>) : <p className="text-xs text-muted">No evidence files submitted.</p>}</div></div></fieldset>; })}
    {checks.some(check=>check.implementation_status==='not_assessed') && <div className="space-y-3 rounded-xl border border-line bg-soft/30 p-4"><h3 className="text-sm font-semibold">Checks left Not assessed</h3><p className="text-xs leading-6 text-muted">You can complete this review with checks left Under review / Not assessed. Explain why they remain unassessed and what is needed next. A shared explanation is used only where an individual rationale is blank; their statuses stay unchanged.</p><Field label="Shared explanation for Not assessed checks"><textarea rows={3} maxLength={5000} value={unassessedReason} onChange={e=>{setUnassessedReason(e.target.value);setEnginePreview(null);setEngineSelection(value=>({...value,evaluationHash:'',disposition:''}));}} placeholder="For example: source configuration evidence has not been supplied; these checks remain unassessed pending the requested records."/></Field></div>}
    </section><section id={stepId+'-panel-1'} data-review-step="1" aria-labelledby={stepId+'-step-1'} hidden={step!==1} className="space-y-5"><p className="text-sm leading-6 text-muted">Record the review decisions below. Add detail where there are gaps, exceptions or further work. Population, operating-history and retest details appear only when required.</p>
    <details className="rounded-xl border border-line bg-soft/30 p-4"><summary className="cursor-pointer text-sm font-semibold">Submitted scope, corrective action and evidence</summary><dl className="mt-4 grid gap-4 text-xs leading-6 sm:grid-cols-2">{[['Affected resources',finding.resources],['Submitted root cause',finding.root_cause],['Submitted corrective action',finding.corrective_action],['Submitted recurrence prevention',finding.recurrence_prevention]].map(([label,value])=><div key={label}><dt className="font-semibold">{label}</dt><dd className="mt-1 whitespace-pre-wrap text-muted">{value||'Not supplied'}</dd></div>)}</dl><p className="mt-4 text-xs leading-6">Submitted evidence: {finding.evidence?.map(file=>`${file.filename} v${file.version}`).join('; ')||'No evidence supplied'}</p></details>
    <nav aria-label="Review judgement sections" className="flex flex-wrap gap-2">{sections.filter(section => section.id !== 'conclusion').map(section => <a key={section.id} href={'#judgement-' + section.id} className="rounded-lg border border-line px-3 py-2 text-xs text-accent">{section.title}</a>)}</nav>
    {sections.filter(section => section.id !== 'conclusion').map(renderJudgementSection)}
    {engineEnabled&&<><ReviewSourcesEditor finding={finding} value={reviewSources} onChange={setReviewSources}/><RulesAssessment panel="inputs" reused={reusedAssessment.reused} inheritedSources={reusedAssessment.inheritedSources} onEntryChange={(id,patch)=>setEngineDraft(previous=>({...previous,entries:{...previous.entries,[id]:{...(('value' in patch?previous.entries[id]:effectiveEngineDraft.entries[id])||{value:'',basis:'',locator:'',evidenceIds:[]}),...patch}}}))} finding={finding} checks={prepareCompletionChecks(checks,unassessedReason).checks} draft={effectiveEngineDraft} onDraft={draft=>{const entries={...draft.entries};for(const id of Object.keys(reusedAssessment.reused))delete entries[id];setEngineDraft({...draft,entries});}} selection={engineSelection} onSelection={setEngineSelection} preview={enginePreview} onPreview={setEnginePreview} onRecommendation={setRecommendation}/></>}





    </section><section id={stepId+'-panel-2'} data-review-step="2" aria-labelledby={stepId+'-step-2'} hidden={step!==2} className="space-y-5">
    {engineEnabled&&<RulesAssessment onSourceIssue={showAssessmentSourceIssue} panel="result" finding={finding} checks={prepareCompletionChecks(checks,unassessedReason).checks} draft={effectiveEngineDraft} onDraft={setEngineDraft} selection={engineSelection} onSelection={setEngineSelection} preview={enginePreview} onPreview={value=>{setEnginePreview(value);if(value)setError('');}} onRecommendation={setRecommendation}/>}
    {sections.filter(section => section.id === 'conclusion').map(renderJudgementSection)}
    <Field label="Review conclusion and rationale"><textarea name="reviewer_conclusion" rows={4} minLength={10} maxLength={2000} value={conclusion} onChange={e=>setConclusion(e.target.value)} placeholder="Explain what the evidence establishes, why the recommendation is appropriate and any remaining limitations." /></Field><p className="text-xs leading-6 text-muted">This conclusion is used in the assessment and report. Required next actions are recorded above.</p>
    <label className="flex items-start gap-3 text-xs leading-6"><input type="checkbox" className="mt-1" checked={independent} onChange={e => setIndependent(e.target.checked)} />I declare that I am independent of the remediation and evidence preparation.</label><Field label="Independence relationship / limitations"><textarea name="independence_notes" rows={2} maxLength={5000} defaultValue={current?.independence_notes || ''} /></Field>
    <div className="rounded-xl border border-accent/25 bg-soft/40 p-4 space-y-4"><Field label={engineEnabled?'Recorded reviewer recommendation':'Reviewer recommendation (manually selected)'}><select disabled={engineEnabled&&engineSelection.disposition==='accept'} value={recommendation} onChange={e => setRecommendation(e.target.value as Readiness | '')}><option value="">No recommendation entered</option>{readiness.map(s => <option key={s}>{s}</option>)}</select></Field>{recommendation === 'Ready for retest' && !includesModule('retest') && <Notice>Request a scope correction to include the retest section. Save your draft while the submission owner addresses the request.</Notice>}{recommendation === 'Closure ready' && <label className="flex items-start gap-3 text-xs leading-6"><input type="checkbox" className="mt-1" checked={!!judgement.closure_ready_acknowledged} onChange={e => setJudgement(j => ({ ...j, closure_ready_acknowledged: e.target.checked }))} />I have explained the basis for closure readiness, including unassessed or incomplete controls, remaining exceptions, operating-history limitations and retest status. This is the recommendation I am recording.</label>}<p className="text-xs leading-6 text-muted">{engineEnabled?'The engine applies the recorded protocol to confirmed facts. Your disposition and any override are preserved. Completion does not formally close the finding.':'The application records your judgement. It does not infer a state from check results, population counts or elapsed days. Publishing a recommendation does not formally close the finding.'}</p></div>
    </section><div className="flex flex-wrap items-center justify-between gap-3 border-t border-line pt-5"><Button secondary type="submit" data-review-action="draft" disabled={busy}>Save review draft</Button><div className="flex flex-wrap gap-3">{step>0&&<Button secondary type="button" disabled={busy} onClick={()=>goToStep(step-1)}>Back</Button>}{step<2?<Button key="next" type="button" disabled={busy} onClick={()=>goToStep(step+1)}>Next</Button>:<Button key="complete" type="submit" data-review-action="complete" disabled={busy}>{busy?'Saving…':'Complete Review'}</Button>}</div></div></form></Card>;
}

function ReviewHistory({ finding }: { finding: ManualFinding }) {
  return <Card>{!!finding.legacyReviews?.length && <section className="mb-6 space-y-4"><h2 className="font-display text-xl font-semibold">Earlier review records</h2><p className="text-xs leading-6 text-muted">Preserved from the earlier database. These decisions contain no structured checklist snapshot and are not treated as a current readiness recommendation.</p>{finding.legacyReviews.map(r => <div key={r.id} className="rounded-xl border border-line p-4"><p className="text-sm font-semibold">{r.decision || 'Recorded legacy review'}</p><p className="mt-2 whitespace-pre-wrap text-xs leading-6">{r.comment || 'No comment recorded.'}</p><p className="mt-2 text-[10px] text-muted">{r.created_at} · Reviewer ID: {r.reviewer_id || 'Not recorded'}</p></div>)}</section>}<h2 className="mb-5 font-display text-xl font-semibold">Review snapshots</h2>{!finding.reviews?.length ? <Empty description="Saved and published reviews will appear here with their exact evidence and protocol basis." /> : finding.reviews.map(r => <details key={r.id} className="border-t border-line py-4"><summary className="cursor-pointer text-sm font-semibold">{r.reviewer} · {r.status} · revision {r.findingRevision} · {r.stale ? 'Stale — earlier finding/evidence revision' : 'Current basis'}</summary><div className="mt-4 space-y-4 text-xs leading-6"><p>{r.authorship}</p><p><strong>Reviewer recommendation:</strong> {r.recommendation || 'Not entered'}<br />{r.recommendation_reason}</p>{r.rules_assessment&&<RulesTrace snapshot={r.rules_assessment}/>} {r.checks.map(c => <div key={c.check_id}><strong>{r.protocol_snapshot?.checks.find(check => check.id === c.check_id)?.label || c.check_id}: {soaCheckLabel(c)}</strong>{c.applicability && <p>Applicable: {soaApplicabilityOptions.find(option => option.value === c.applicability)?.label}</p>}{c.reason_source === 'shared_unassessed_note' && <p className="text-muted">Shared explanation for unassessed checks</p>}<p className="whitespace-pre-wrap">{c.reason || 'No rationale recorded in draft.'}</p><p>Source location: {c.source_location || 'Not recorded'} · Evidence: {c.evidence_ids.map(id => { const file = r.evidence_snapshot.find(e => e.id === id); return file ? `${file.filename} v${file.version}` : id; }).join(', ') || 'None'}</p></div>)}{r.closure_judgement && <div className="space-y-4"><h3 className="font-semibold">ClosureProof reviewer judgement</h3>{activeSections(r.protocol_snapshot,r.closure_judgement).map(section => <section key={section.id}><h4 className="font-semibold">{section.title}</h4>{judgementFields(section,r.closure_judgement!,r.exception_entries?.length||0).filter(field=>field.required!==false||r.closure_judgement?.[field.key]).map(field => <p key={field.key} className="mt-2 whitespace-pre-wrap"><strong>{field.label}:</strong> {r.closure_judgement?.[field.key] || 'Not recorded'}</p>)}</section>)}</div>}{r.protocol_snapshot.review_scope && <div><p>Controls: {r.protocol_snapshot.review_scope.controls.map(c=>c.id).join(', ')||'Provisional custom scope'} · Mapping {r.protocol_snapshot.review_scope.version}</p><p>Scope confirmed: {r.scope_confirmed?'Yes':'Not recorded'} · {r.scope_confirmation_notes}</p>{Object.entries(r.protocol_snapshot.review_scope.module_exclusions).map(([id,reason])=><p key={id}>{id}: Outside this assessment scope — {reason}</p>)}{Object.entries(r.protocol_snapshot.review_scope.excluded_tasks).map(([id,reason])=><p key={id}>{id}: Outside this assessment scope — {reason}</p>)}</div>}{!['2.0-manual',JUDGEMENT_VERSION].includes(r.closure_judgement?.version||'') && <div>{([['population_notes','Earlier population notes'],['exceptions','Earlier exception notes'],['operating_period_notes','Earlier operating-history notes'],['retest_notes','Earlier retest notes']] as const).map(([key,label])=>r[key]?<p key={key}><strong>{label}:</strong> {r[key]}</p>:null)}</div>}{['2.0-manual',JUDGEMENT_VERSION].includes(r.closure_judgement?.version||'') && <div>{r.exception_entries?.map(entry=><div key={entry.reference} className="mt-3 border-t border-line pt-3"><strong>{entry.reference}: {entry.description}</strong><p>Owner: {entry.owner} · {entry.disposition} · {entry.closure_impact}</p><p>Evidence: {entry.evidence_reference||'Not recorded'}</p>{entry.disposition==='accepted'&&<p>Accepted by: {entry.acceptance_authority} · {entry.acceptance_date} · {entry.acceptance_reference}</p>}{entry.compensating_controls&&<p>Compensating controls: {entry.compensating_controls}</p>}</div>)}{Object.entries(r.closure_judgement?.evidence_refs||{}).map(([section,ids])=><p key={section}>Evidence supporting {section}: {ids.map(id=>{const file=r.evidence_snapshot.find(file=>file.id===id);return file?`${file.filename} v${file.version}`:id;}).join(', ')||'None linked'}</p>)}</div>}{r.ai_confirmed_facts?.length? <section><h3 className="font-semibold">Confirmed document facts</h3>{r.ai_confirmed_facts.map(fact=><div key={fact.confirmation_id} className="mt-3"><p>{fact.label}: {fact.value}</p><p>{fact.filename} v{fact.evidence_version} · {fact.actor} · {fact.confirmed_at}</p><SourceQuote source={fact}/></div>)}</section>:null}<p>Clarification: {r.clarification_request || 'None recorded'}</p></div></details>)}</Card>;
}

function ManualTimeline({ id }: { id: string }) {
  const [events, setEvents] = useState<TimelineEvent[]>([]); const [error, setError] = useState('');
  useEffect(() => { manualApi.timeline(id).then(setEvents).catch(e => setError(errorText(e))); }, [id]);
  return <Card><h2 className="mb-5 font-display text-xl font-semibold">Activity timeline</h2>{error && <Notice error>{error}</Notice>}{events.map(e => <div key={e.id} className="border-t border-line py-4"><h3 className="text-sm font-semibold">{e.title}</h3><p className="mt-2 text-xs leading-6 text-muted">{e.detail}</p><p className="mt-2 text-[10px] text-muted">Revision {e.revision} · {new Date(e.timestamp).toLocaleString('en-GB', { timeZone: 'UTC' })} UTC</p></div>)}</Card>;
}

export function ManualProtocolsPage() { return <ISOProtocolLibrary />; }


function SubmissionCard({submission,onOpen,action='View evidence'}:{submission:EvidenceSubmission;onOpen:()=>void;action?:string}) {
 return <button type="button" onClick={onOpen} aria-label={action+' for '+submission.name} className="min-w-0 rounded-2xl border border-line bg-white p-5 text-left transition hover:border-accent/50 focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-accent"><div className="flex items-start gap-3"><FileText className="mt-1 shrink-0 text-accent" size={22}/><div className="min-w-0 flex-1"><p className="text-[11px] font-semibold text-muted">{submission.report?'Audit report':'Finding submission'}</p><h2 className="mt-1 break-words text-sm font-semibold [overflow-wrap:anywhere]">{submission.name}</h2><SubmissionReadiness submission={submission}/><SubmissionMetadata submission={submission}/><p className="mt-4 border-t border-line pt-3 text-xs text-muted">{submission.findings.length} finding(s) · {submission.evidenceCount} evidence file(s)</p><span className="mt-4 inline-flex items-center gap-2 text-xs font-semibold text-accent">{action}<ArrowRight size={14}/></span></div></div></button>;
}
function ReviewSubmissionList({findings,filtered,queue=true}:{findings:ManualFinding[];filtered:boolean;queue?:boolean}) {
 const [params,setParams]=useSearchParams();
 const {manualFindings}=useWorkspace();
 const visibleIds=new Set(findings.map(finding=>finding.id));
 const groups=evidenceSubmissions(manualFindings).filter(group=>group.findings.some(finding=>visibleIds.has(finding.id)));
 const selected=groups.find(group=>group.key===params.get('submission'));
 function select(key?:string){const next=new URLSearchParams(params);if(key)next.set('submission',key);else next.delete('submission');setParams(next);}
 if(!groups.length)return <ManualFindingList findings={[]} queue filtered={filtered}/>;
 if(selected){
   return <div className="space-y-5"><Button type="button" secondary size="compact" onClick={()=>select()}><ArrowLeft size={14}/>Back to submissions</Button><Card><div className="flex flex-wrap items-center justify-between gap-3"><p className="text-xs font-semibold text-accent">Submission reviews</p><SubmissionReadiness submission={selected}/></div><h2 className="mt-2 break-words font-display text-xl font-semibold">{selected.name}</h2><SubmissionMetadata submission={selected}/></Card><ManualFindingList findings={selected.findings} queue={queue}/></div>;
 }

 return <div className="grid gap-4 md:grid-cols-2">{groups.map(group=><SubmissionCard key={group.key} submission={group} action="View findings" onOpen={()=>select(group.key)}/>)}</div>;
}

function SubmissionReadiness({submission}:{submission:EvidenceSubmission}) {
 const {manualFindings}=useWorkspace();
 const all=evidenceSubmissions(manualFindings).find(group=>group.key===submission.key)?.findings||submission.findings;
 const ready=submissionClosureReady(all);
 return <Badge tone={ready?'green':'red'}>{ready?'All findings closure-ready':'Not ready for closure'}</Badge>;
}

function SubmissionMetadata({submission}:{submission:EvidenceSubmission}) {
  const unique=(values:(string|undefined)[])=>[...new Set(values.filter((value):value is string=>Boolean(value?.trim())))].join(', ')||'Not recorded';
  const statuses=new Map<string,number>();
  for(const finding of submission.findings)statuses.set(finding.lifecycle,(statuses.get(finding.lifecycle)||0)+1);
  const metadata=[
    ['Submission ID',submission.reference||submission.id],
    ['Date submitted',submission.firstSubmitted?new Date(submission.firstSubmitted).toLocaleString('en-GB',{dateStyle:'medium',timeStyle:'short'}):'Not recorded'],
    ['Remediation owner',unique(submission.findings.map(f=>f.owner))],
    ['Controls',unique(submission.findings.map(f=>f.control_reference))],
    ['Environment',unique(submission.findings.map(f=>f.account_reference))],
    ['Finding status',[...statuses].map(([status,count])=>`${workflow(status)} (${count})`).join(' · ')],
    ...(submission.report?[['Report confirmed by',unique(submission.findings.map(f=>f.source_report?.confirmed_by))]]:[]),
  ];
  return <dl className="mt-4 grid gap-x-5 gap-y-3 text-xs sm:grid-cols-2">{metadata.map(([label,value])=><div key={label} className={label==='Submission ID'?'sm:col-span-2':''}><dt className="text-[11px] text-muted">{label}</dt><dd className="mt-1 break-words font-medium [overflow-wrap:anywhere]">{value}</dd></div>)}</dl>;
}

export function ManualEvidencePage() {
  const { manualFindings, loading: workspaceLoading, error: workspaceError } = useWorkspace();
  const [params,setParams] = useSearchParams();
  const [search,setSearch] = useState('');
  const [findings, setFindings] = useState<ManualFinding[]>([]);
  const [loadedKey,setLoadedKey] = useState('');
  const [loading, setLoading] = useState(false); const [error, setError] = useState('');
  const [refreshKey,setRefreshKey] = useState(0);
  const submissions = evidenceSubmissions(manualFindings);
  const selected = submissions.find(group=>group.key===params.get('submission'));
  const revisions = selected?.findings.map(f=>`${f.id}:${f.revision}`).join('|') || '';
  const selectedKey = selected?.key;
  useEffect(()=>{
    let cancelled=false;
    setFindings([]);setLoadedKey('');setError('');
    if(!selected || workspaceLoading || workspaceError){setLoading(false);return;}
    setLoading(true);
    Promise.all(selected.findings.map(f=>manualApi.finding(f.id))).then(rows=>{if(!cancelled){setFindings(rows);setLoadedKey(selected.key);}}).catch(e=>{if(!cancelled)setError(errorText(e));}).finally(()=>{if(!cancelled)setLoading(false);});
    return()=>{cancelled=true;};
  },[selectedKey,revisions,refreshKey,workspaceLoading,workspaceError]);
  function select(key?:string){const next=new URLSearchParams(params);if(key)next.set('submission',key);else next.delete('submission');setParams(next);}
  const matching=submissions.filter(group=>`${group.name} ${group.id} ${group.reference||''} ${group.findings.map(f=>`${f.id} ${f.findingReference||''} ${f.title} ${f.owner}`).join(' ')}`.toLowerCase().includes(search.toLowerCase()));
  return <><PageHeader eyebrow="Submitted files" title="Evidence library" description="Browse submissions, then open a report or finding to inspect its supporting evidence." action={<Link className={secondaryClass} to="/app/findings">View findings</Link>} />
    {workspaceError ? <Card><p className="text-sm text-muted">Evidence records cannot load until the review service reconnects.</p></Card> : workspaceLoading ? <Loading /> : selected ? <>
      <Button type="button" secondary size="compact" onClick={()=>select()}><ArrowLeft size={14}/>Back to submissions</Button>
      <Card className="my-5"><p className="text-xs font-semibold text-accent">{selected.report?'Audit report submission':'Finding submission'}</p><h2 className="mt-2 break-words font-display text-xl font-semibold [overflow-wrap:anywhere]">{selected.name}</h2><SubmissionMetadata submission={selected}/><p className="mt-4 border-t border-line pt-3 text-xs text-muted">{selected.findings.length} finding(s) · {selected.evidenceCount} evidence file(s)</p></Card>
      {error ? <Notice error>{error}</Notice> : loading || loadedKey!==selected.key ? <Loading /> : <div className="space-y-6">{findings.map(f=><section key={f.id} aria-label={'Evidence for '+f.title}><Card className="mb-3"><Link className="inline-flex items-center gap-2 text-sm font-semibold text-accent" to={'/app/findings/'+f.id}>{f.title}<ArrowRight size={15}/></Link><p className="mt-2 break-all text-xs text-muted">Finding ID: {f.findingReference||f.id}</p><p className="mt-2 text-xs text-muted">{f.control_reference||f.protocol.title} · {f.owner}</p></Card><EvidenceLibrary finding={f} onSaved={async()=>{setRefreshKey(value=>value+1);}}/></section>)}</div>}
    </> : !submissions.length ? <Empty title="No submissions in the library" description="Submitted findings and their supporting evidence will appear here." /> : <>
      <Card className="mb-5"><Field label="Search submissions"><input value={search} onChange={event=>setSearch(event.target.value)} placeholder="Report name, submission ID, finding or owner"/></Field></Card>
      {!matching.length?<Empty title="No matching submissions" description="Try another report name, ID, finding or owner."/>:<div className="grid gap-4 md:grid-cols-2">{matching.map(group=><SubmissionCard key={group.key} submission={group} onOpen={()=>select(group.key)}/>)}</div>}
    </>}
  </>;
}
